<?php
$page_title='Kiểm tra hồ sơ chuyên môn';
require_once 'includes/functions.php';
require_login();

function fc_norm($value): string {$value=preg_replace('/\s+/u',' ',trim((string)$value));return function_exists('mb_strtolower')?mb_strtolower($value,'UTF-8'):strtolower($value);}
function fc_is_leader(array $user): bool {return ($user['role']??'')==='totruong'||in_array('totruong',(array)($user['groups']??[]),true);}
function fc_teacher_id($name): string {foreach(load_json(dirname(__DIR__).'/data/teachers.json',[]) as $teacher)if(fc_norm($teacher['name']??'')===fc_norm($name))return(string)($teacher['id']??'');return '';}

$user=cds_user()??[];$isAdmin=($user['role']??'')==='admin';$isBgh=($user['role']??'')==='bgh'||in_array('bgh',(array)($user['groups']??[]),true);$isLeader=fc_is_leader($user);$canManage=$isAdmin||$isBgh||$isLeader;
$actorName=trim((string)($user['teacher_name']??$user['name']??''));$actorGroup=$actorName!==''?trim((string)get_teacher_group($actorName)):'';
$allTeachers=get_teachers_sorted();$managedTeachers=[];
foreach($allTeachers as $name)if($isAdmin||$isBgh||($isLeader&&$actorGroup!==''&&fc_norm(get_teacher_group($name))===fc_norm($actorGroup)))$managedTeachers[]=$name;
$dataFile=DATA_PATH.'/professional_file_checks.json';$records=load_json($dataFile,[]);if(!is_array($records))$records=[];
if(empty($_SESSION['fc_csrf']))$_SESSION['fc_csrf']=bin2hex(random_bytes(20));$csrf=$_SESSION['fc_csrf'];
$canSee=function(array $row)use($isAdmin,$isBgh,$isLeader,$actorGroup,$actorName){if($isAdmin||$isBgh)return true;if($isLeader&&$actorGroup!==''&&fc_norm($row['teacher_group']??'')===fc_norm($actorGroup))return true;return fc_norm($row['teacher_name']??'')===fc_norm($actorName);};

if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals($csrf,(string)($_POST['csrf']??''))){http_response_code(403);exit('Phiên làm việc không hợp lệ.');}
    $action=(string)($_POST['action']??'');
    if($action==='file_check_save'){
        if(!$canManage){http_response_code(403);exit('Chỉ tổ trưởng, BGH hoặc quản trị được cập nhật kiểm tra hồ sơ.');}
        $teacherName=trim((string)($_POST['teacher_name']??''));$date=trim((string)($_POST['date']??''));$content=trim((string)($_POST['content']??''));$result=trim((string)($_POST['result']??''));$rating=trim((string)($_POST['rating']??''));
        if(!in_array($teacherName,$managedTeachers,true)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$content===''||$result===''||!in_array($rating,['Tốt','Khá','Đạt','Chưa đạt'],true)){flash('Vui lòng nhập đầy đủ và đúng phạm vi kiểm tra.','danger');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;}
        $records[]=['id'=>'fc_'.bin2hex(random_bytes(8)),'teacher_id'=>fc_teacher_id($teacherName),'teacher_name'=>$teacherName,'teacher_group'=>trim((string)get_teacher_group($teacherName)),'inspector_id'=>$user['id']??'','inspector_name'=>$actorName,'date'=>$date,'content'=>$content,'result'=>$result,'rating'=>$rating,'created_by'=>$user['id']??'','created_at'=>date('c'),'updated_at'=>date('c')];
        save_json($dataFile,array_values($records));flash('Đã lưu kết quả kiểm tra hồ sơ chuyên môn.');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;
    }
    if($action==='file_check_delete'){
        if(!$isAdmin){http_response_code(403);exit('Chỉ quản trị được xóa kết quả kiểm tra.');}
        $id=trim((string)($_POST['id']??''));$records=array_values(array_filter($records,fn($row)=>($row['id']??'')!==$id));save_json($dataFile,$records);flash('Đã xóa kết quả kiểm tra.','warning');header('Location: '.BASE_URL.'kiemtrahoso.php');exit;
    }
}

$visible=array_values(array_filter($records,$canSee));usort($visible,fn($a,$b)=>strcmp(($b['date']??'').'|'.($b['created_at']??''),($a['date']??'').'|'.($a['created_at']??'')));
$view=($_GET['view']??'')==='stats'?'stats':'list';$from=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['from']??'')?(string)$_GET['from']:'';$to=preg_match('/^\d{4}-\d{2}-\d{2}$/',$_GET['to']??'')?(string)$_GET['to']:'';if($from&&$to&&$from>$to)[$from,$to]=[$to,$from];
$group=trim((string)($_GET['group']??''));$teacherFilter=trim((string)($_GET['teacher']??''));$inspector=trim((string)($_GET['inspector']??''));$ratingFilter=trim((string)($_GET['rating']??''));
$stats=array_values(array_filter($visible,fn($row)=>(!$from||($row['date']??'')>=$from)&&(!$to||($row['date']??'')<=$to)&&(!$group||($row['teacher_group']??'')===$group)&&(!$teacherFilter||($row['teacher_name']??'')===$teacherFilter)&&(!$inspector||($row['inspector_name']??'')===$inspector)&&(!$ratingFilter||($row['rating']??'')===$ratingFilter)));
$groups=array_values(array_unique(array_filter(array_column($visible,'teacher_group'))));sort($groups,SORT_NATURAL|SORT_FLAG_CASE);$inspectors=array_values(array_unique(array_filter(array_column($visible,'inspector_name'))));sort($inspectors,SORT_NATURAL|SORT_FLAG_CASE);
$summary=[];foreach($stats as $row){$key=trim((string)($row['teacher_group']??''))?:'Chưa xếp tổ';if(!isset($summary[$key]))$summary[$key]=['total'=>0,'people'=>[],'Tốt'=>0,'Khá'=>0,'Đạt'=>0,'Chưa đạt'=>0];$summary[$key]['total']++;$summary[$key]['people'][$row['teacher_id']?:fc_norm($row['teacher_name'])]=true;$rating=$row['rating']??'';if(isset($summary[$key][$rating]))$summary[$key][$rating]++;}
require_once 'includes/header.php';
?>
<style>.fc-toolbar{display:flex;justify-content:space-between;gap:1rem;align-items:center;margin-bottom:1rem}.fc-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:.85rem}.fc-form .wide{grid-column:span 2}.fc-table{min-width:1120px;table-layout:fixed}.fc-table th{text-align:center}.fc-table td{vertical-align:middle;overflow-wrap:anywhere}.fc-filter{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:.7rem;align-items:end}.fc-kpis{display:grid;grid-template-columns:repeat(5,1fr);gap:.7rem}.fc-kpis>div{padding:1rem;text-align:center}.fc-kpis strong{display:block;font-size:1.55rem;color:var(--primary)}.fc-kpis span{font-size:.78rem;color:#64748b}.fc-summary{min-width:760px}.fc-summary th,.fc-summary td{text-align:center}.fc-summary td:nth-child(2){text-align:left}@media(max-width:767px){.fc-toolbar{align-items:flex-start;flex-direction:column}.fc-form,.fc-filter{grid-template-columns:1fr 1fr}.fc-form .wide{grid-column:1/-1}.fc-kpis{grid-template-columns:1fr 1fr}.fc-kpis>div:first-child{grid-column:1/-1}}</style>
<div class="fc-toolbar"><div><h3 class="mb-1"><i class="bi bi-folder-check text-primary"></i> Kiểm tra hồ sơ chuyên môn</h3><div class="text-muted">Ghi nhận, theo dõi và thống kê kết quả kiểm tra hồ sơ giáo viên</div></div><div class="btn-group"><a class="btn <?=$view==='list'?'btn-primary':'btn-outline-primary'?>" href="<?=BASE_URL?>kiemtrahoso.php"><i class="bi bi-table"></i> Danh sách</a><a class="btn <?=$view==='stats'?'btn-primary':'btn-outline-primary'?>" href="<?=BASE_URL?>kiemtrahoso.php?view=stats"><i class="bi bi-bar-chart-line"></i> Thống kê</a></div></div>
<?php if($view==='list'):?><?php if($canManage):?><section class="card mb-3"><div class="card-header">Ghi nhận kiểm tra hồ sơ</div><div class="card-body"><form method="post"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="file_check_save"><div class="fc-form"><div><label class="form-label fw-semibold">Giáo viên được kiểm tra</label><select class="form-select" name="teacher_name" required><option value="">Chọn giáo viên</option><?php foreach($managedTeachers as $name):?><option value="<?=e($name)?>"><?=e($name)?> · <?=e(get_teacher_group($name))?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Người kiểm tra</label><input class="form-control" value="<?=e($actorName)?>" disabled></div><div><label class="form-label fw-semibold">Ngày kiểm tra</label><input class="form-control" type="date" name="date" value="<?=date('Y-m-d')?>" required></div><div class="wide"><label class="form-label fw-semibold">Nội dung kiểm tra</label><textarea class="form-control" name="content" rows="3" required></textarea></div><div><label class="form-label fw-semibold">Xếp loại</label><select class="form-select" name="rating" required><option value="">Chọn xếp loại</option><option>Tốt</option><option>Khá</option><option>Đạt</option><option>Chưa đạt</option></select></div><div class="wide"><label class="form-label fw-semibold">Kết quả kiểm tra</label><textarea class="form-control" name="result" rows="3" required></textarea></div></div><button class="btn btn-primary mt-3"><i class="bi bi-floppy"></i> Lưu kết quả</button></form></div></section><?php endif;?>
<section class="card"><div class="card-header d-flex justify-content-between"><span>Danh sách kiểm tra hồ sơ</span><span><?=count($visible)?> lượt</span></div><div class="table-responsive"><table class="table table-bordered table-hover mb-0 fc-table"><colgroup><col style="width:52px"><col style="width:175px"><col style="width:140px"><col style="width:175px"><col style="width:105px"><col style="width:230px"><col style="width:265px"><col style="width:95px"><col style="width:70px"></colgroup><thead><tr><th>STT</th><th>Giáo viên được kiểm tra</th><th>Tổ</th><th>Người kiểm tra</th><th>Ngày</th><th>Nội dung kiểm tra</th><th>Kết quả kiểm tra</th><th>Xếp loại</th><th></th></tr></thead><tbody><?php foreach($visible as $i=>$row):?><tr><td class="text-center"><?=$i+1?></td><td><strong><?=e($row['teacher_name']??'')?></strong></td><td><?=e($row['teacher_group']??'')?></td><td><?=e($row['inspector_name']??'')?></td><td class="text-center"><?=!empty($row['date'])?date('d/m/Y',strtotime($row['date'])):''?></td><td><?=nl2br(e($row['content']??''))?></td><td><?=nl2br(e($row['result']??''))?></td><td class="text-center"><span class="badge <?=($row['rating']??'')==='Tốt'?'bg-success':(($row['rating']??'')==='Khá'?'bg-info text-dark':(($row['rating']??'')==='Đạt'?'bg-warning text-dark':'bg-danger'))?>"><?=e($row['rating']??'')?></span></td><td class="text-center"><?php if($isAdmin):?><form method="post" onsubmit="return confirm('Xóa kết quả kiểm tra này?')"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><input type="hidden" name="action" value="file_check_delete"><input type="hidden" name="id" value="<?=e($row['id']??'')?>"><button class="btn btn-sm btn-outline-danger"><i class="bi bi-trash"></i></button></form><?php endif;?></td></tr><?php endforeach;if(!$visible):?><tr><td colspan="9" class="text-center text-muted py-4">Chưa có dữ liệu kiểm tra hồ sơ.</td></tr><?php endif;?></tbody></table></div></section>
<?php else:?><form class="card mb-3" method="get"><input type="hidden" name="view" value="stats"><div class="card-body fc-filter"><div><label class="form-label fw-semibold">Từ ngày</label><input class="form-control" type="date" name="from" value="<?=e($from)?>"></div><div><label class="form-label fw-semibold">Đến ngày</label><input class="form-control" type="date" name="to" value="<?=e($to)?>"></div><div><label class="form-label fw-semibold">Tổ chuyên môn</label><select class="form-select" name="group"><option value="">Tất cả tổ</option><?php foreach($groups as $item):?><option <?=$item===$group?'selected':''?>><?=e($item)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Giáo viên</label><select class="form-select" name="teacher"><option value="">Tất cả giáo viên</option><?php foreach($allTeachers as $name):?><option <?=$name===$teacherFilter?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Người kiểm tra</label><select class="form-select" name="inspector"><option value="">Tất cả</option><?php foreach($inspectors as $name):?><option <?=$name===$inspector?'selected':''?>><?=e($name)?></option><?php endforeach;?></select></div><div><label class="form-label fw-semibold">Xếp loại</label><select class="form-select" name="rating"><option value="">Tất cả</option><?php foreach(['Tốt','Khá','Đạt','Chưa đạt'] as $item):?><option <?=$item===$ratingFilter?'selected':''?>><?=$item?></option><?php endforeach;?></select></div><button class="btn btn-primary"><i class="bi bi-funnel"></i> Áp dụng</button><a class="btn btn-outline-secondary" href="<?=BASE_URL?>kiemtrahoso.php?view=stats">Xóa lọc</a></div></form><div class="fc-kpis mb-3"><div class="card"><strong><?=count($stats)?></strong><span>Tổng lượt kiểm tra</span></div><?php foreach(['Tốt','Khá','Đạt','Chưa đạt'] as $item):?><div class="card"><strong><?=count(array_filter($stats,fn($row)=>($row['rating']??'')===$item))?></strong><span><?=$item?></span></div><?php endforeach;?></div><section class="card mb-3"><div class="card-header">Tổng hợp theo tổ</div><div class="table-responsive"><table class="table table-bordered mb-0 fc-summary"><thead><tr><th>STT</th><th>Tổ chuyên môn</th><th>Số giáo viên</th><th>Lượt kiểm tra</th><th>Tốt</th><th>Khá</th><th>Đạt</th><th>Chưa đạt</th></tr></thead><tbody><?php $i=0;foreach($summary as $name=>$row):?><tr><td><?=++$i?></td><td><strong><?=e($name)?></strong></td><td><?=count($row['people'])?></td><td><?=$row['total']?></td><td><?=$row['Tốt']?></td><td><?=$row['Khá']?></td><td><?=$row['Đạt']?></td><td><?=$row['Chưa đạt']?></td></tr><?php endforeach;if(!$summary):?><tr><td colspan="8" class="text-center text-muted py-4">Chưa có dữ liệu trong phạm vi lọc.</td></tr><?php endif;?></tbody></table></div></section><section class="card"><div class="card-header">Bảng kê chi tiết</div><div class="table-responsive"><table class="table table-bordered mb-0 fc-table"><thead><tr><th>STT</th><th>Giáo viên</th><th>Tổ</th><th>Người kiểm tra</th><th>Ngày</th><th>Nội dung</th><th>Kết quả</th><th>Xếp loại</th></tr></thead><tbody><?php foreach($stats as $i=>$row):?><tr><td class="text-center"><?=$i+1?></td><td><?=e($row['teacher_name']??'')?></td><td><?=e($row['teacher_group']??'')?></td><td><?=e($row['inspector_name']??'')?></td><td class="text-center"><?=date('d/m/Y',strtotime($row['date']))?></td><td><?=e($row['content']??'')?></td><td><?=e($row['result']??'')?></td><td class="text-center"><?=e($row['rating']??'')?></td></tr><?php endforeach;if(!$stats):?><tr><td colspan="8" class="text-center text-muted py-4">Chưa có dữ liệu.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?>
<?php require_once 'includes/footer.php';?>
